(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["sr"] = {"ui":{"skip":"Пређи на садржај","back":"← Назад на AI-gile","lang.button":"Језик: {name}","lang.dialog":"Изабери језик","lang.search":"Претражи језике","lang.none":"Ниједан језик не одговара","lang.notYet":"{name} још није преведен","theme.aria":"Промени тему: светла, тамна или црна","theme.toLight":"Пређи на светлу тему","theme.toDark":"Пређи на тамну тему","theme.toBlack":"Пређи на црну тему (права црна, пријатна за OLED екране)","words.underline":"Подвуци ове речи на страници","words.underlineHelp":"Пређи мишем преко истачкане речи или је додирни да видиш шта значи.","index.title":"AI-gile: твој AI тим програмера на једној табли","index.description":"AI-gile је канбан табла за AI тимове који пишу код. Они раде док ти спаваш; ти добијеш једну кратку гомилу ствари да одлучиш, тестираш и прихватиш.","hero.logoAlt":"Икона AI-gile табле","hero.h1.html":"Твој AI тим програмера на једној&nbsp;табли.","hero.alpha":"🐣 Затворена пре-алфа","hero.alphaTitle":"Рано и недовршено: хвала што пробаш!","hero.lede":"Они граде док ти спаваш. Будиш се уз једну кратку гомилу: пар питања, пар ствари за тест, један или два љубичаста дијаманта. Кликни, прихвати, и назад на кафу.","dl.windows":"Windows апликација","dl.browser":"Покрени у прегледачу","dl.messenger":"📱 Messenger за твој телефон","dl.soon":"Ускоро","dl.notify":"🔔 Јави ми кад се отвори","dl.notifySmall":"Алфа или бета","hero.secondary":"Agile, али тиму никад не треба кафа за стендап. (Стендап ипак држе.)","pitch.h2":"AI-gile у онолико речи колико хоћеш","pitch.lede":"Изабери дужину, од једне речи до 144. Свака дужина је посебан опис, написан баш за ту величину. Повуци клизач или користи стрелице.","pitch.rangeLabel":"Дужина у речима","pitch.dice":"🎲 друга верзија","pitch.words.one":"{n} реч","pitch.words.other":"{n} речи","pitch.letters.one":"{n} слово","pitch.letters.other":"{n} слова","pitch.chars.one":"{n} знак","pitch.chars.other":"{n} знакова","count.line.html.one":"{n} картица на табли управо сад","count.line.html.other":"{n} картица на табли управо сад","people.humans.html.one":"👥 {n} човек","people.humans.html.other":"👥 {n} људи","people.agents.html.one":"🤖 {n} агент","people.agents.html.other":"🤖 {n} агената","people.working.html.one":"⚡ {n} на послу управо сад","people.working.html.other":"⚡ {n} на послу управо сад","pre.title":"AI-gile: овде се нешто гради","pre.description":"Овде се нешто гради: табла на којој AI тимови граде оно што тражиш и уче те успут. За сада затворена пре-алфа са пријатељима.","pre.h1":"Овде се нешто гради. 🤫","pre.line":"Табла на којој AI тимови граде оно што тражиш и уче те успут. За сада затворена пре-алфа са пријатељима.","pre.btn":"🔔 Јави ми кад се отвори","pre.peek":"Иза стакла: права табла, уживо. Свака картица је обојена трака.","pre.peekFake":"Иза стакла: овако изгледа табла на делу.","features.aria":"Шта ради","f.pile.h":"Једна гомила за тебе","f.pile.html":"<b>За тебе</b> држи све што чека тебе, преко свих пројеката: питања, ствари за тест, задатке које може само човек. Твој ред каже шта је следеће и колико траје.","f.sleep.h":"Тимови који раде док ти спаваш","f.sleep.p":"Сваки пројекат има вођу и тим AI агената. Коментариши картицу и тим се буди, одради посао и врати је са корацима које може да прати и уморан човек.","f.tester.h":"AI тестер проверава први","f.tester.p":"Пре него што нешто стигне до тебе, тестер прати кораке у копији апликације и показује шта је видео, са снимком екрана. Прелистај оне који су прошли и прихвати једним кликом.","f.proof.h":"Докази, не обећања","f.proof.p":"Свака предаја показује шта се променило: фајлове, разлику, снимке екрана. Не мораш да отвараш сваку апликацију да видиш да ли је готово.","f.chat.h":"Ћаскај са својим вођама","f.chat.p":"Трака као на Discordu: једна икона по пројекту, љубичасти дијаманти за оно што треба тебе. Пошаљи вођи идеју; он је претвори у картице и план, са дугметом ✅ Крени.","f.tidy.h":"Сама се сређује","f.tidy.p":"Сродне картице се спајају у једну, збркани наслови се поправљају, а провера токена држи код сажетим. Мање ствари између којих се пребацујеш, мање мисли.","f.private.h":"Твоје, на твом рачунару","f.private.li1":"Табла ради на твом рачунару и одговара само теби.","f.private.li2":"Приватне поруке међу људима су шифроване од краја до краја.","f.private.li3":"Без налога, без трагача, без колачића.","f.lang.h":"На твом језику","f.lang.p":"Преко 120 језика, од холандског, велшког и јапанског до гусарског, Јоде и клингонског, уз брзи повратак на енглески за стручне изразе.","f.service.h":"Од идеје до правог сервиса","f.service.p":"Направио си нешто са AI што људи сада користе? Означи то као сервис и табла ти помаже да га добро водиш: провере доступности, јавна страница статуса, инциденти са анализом, измене којима треба Go, резервне копије проверене сваки дан. Помоћ те учи сваки корак док радиш.","msgr.h2":"AI-gile Messenger: твој тим у џепу","msgr.p1":"Разговарај са својим AI тимом без отварања табле. Ћаскај са вођама пројеката и пријатељима, погледај кораке за тестирање картице и одговори на њих, све са телефона.","msgr.p2":"Да га повежеш, скенирај QR код на својој табли. Први пут? Пријатељско демо ћаскање ће ти све показати.","msgr.when":"Прво Android, затим веб верзија за телефоне и iPhone.","msgr.who":"Твој вођа пројекта","msgr.b1":"Исправка тамног режима је спремна. Хоћеш кораке за тестирање?","msgr.b2":"Да, молим!","msgr.b3":"1. Отвори Подешавања. 2. Изабери Тамно. Да ли изгледа како треба?","tl.aria":"Временска линија од првог разговора до плана","tl.h2":"Од првог ћаскања до онога што следи","tl.lede":"Прави датуми и сати, у твојој временској зони. После данас то је план, без обећаних датума.","tl.today":"Данас","tl.planned":"планирано","tl.cards.one":"{n} картица","tl.cards.other":"{n} картица","join.h2":"Придружи се","join.lede":"AI-gile праве брадати чудак са AuDHD-ом и неколико битака за ментално здравље и много стрпљивих агената. За сада је приватан, у затвореној алфи са пријатељима. Хоћеш да пробаш кад се отвори?","join.btn":"Пријави интересовање","join.small":"Послаћемо ти мејл, ништа друго","footer.tag":"AI-gile. Без трагача, без колачића, без кафе за стендап.","footer.licence":"Пословна лиценца","footer.status":"Статус","footer.privacy":"Шта чувамо","footer.thanks":"Позиви захваљујући ChilledChat-у","form.sending":"Шаље се…","form.failed":"Није успело: покушај поново касније.","form.offline":"Није могуће допрети до AI-gile: покушај поново касније.","form.keep":"Ово користимо само да ти одговоримо, а затим бришемо. Без трагача, без колачића.","form.keepLink":"Шта чувамо","interest.title":"AI-gile: јави ми кад се алфа отвори","interest.description":"Остави мејл да чујеш кад се отвори затворена алфа или бета AI-gile.","interest.h1":"🔔 Јави ми кад се отвори","interest.lede":"AI-gile је у затвореној пре-алфи. Остави мејл и јавићемо се једном, кад буде места за тебе.","interest.email":"Твој мејл","interest.which":"Који тест?","interest.alpha":"Затворена алфа: рано, грубо, пуно промена","interest.beta":"Бета: стабилнија, касније","interest.both":"Било која, шта прво дође","interest.submit":"Упиши ме на листу","interest.thanks":"Хвала! На листи си.","licence.title":"AI-gile: пословна лиценца","licence.description":"Користиш AI-gile у послу? Затражи бесплатну пословну лиценцу.","licence.h1":"📜 Пословна лиценца","licence.lede":"Користиш AI-gile на послу? Реци нам ко си и чиме се бавиш. Ако то чини нешто добро, лиценца је бесплатна.","licence.company":"Компанија","licence.website":"Веб-сајт","licence.what":"Чиме се бавиш","licence.how":"Како помаже свету","licence.email":"Мејл","licence.submit":"Пријави се","licence.thanks":"Хвала! Одговорићемо мејлом.","status.title":"AI-gile статус","status.h1":"AI-gile статус","status.quiet":"Све мирно","status.intro":"Да ли AI-gile ради управо сада? Ова страница на сваких 5 минута проверава сајт, дељење табли, позиве и преузимање.","status.up":"Ради (одговор за {ms} ms)","status.slow":"Нема одговора на последњу проверу, покушавам поново","status.down":"Не ради: нема одговора на последње две провере","status.svc.web":"Сајт","status.svc.web.offers":"Овај сајт: шта је AI-gile и формулар за интересовање","status.svc.boards":"Дељење табли","status.svc.boards.offers":"Јавне табле, поруке између пријатеља и позивнице","status.svc.calls":"Позиви","status.svc.calls.offers":"Глас, видео и дељење екрана у AI-gile","status.svc.download":"Преузимање","status.svc.download.offers":"Windows инсталер и линкови за позивнице","status.checking":"Проверавам…","status.offline":"Тренутно не могу да допрем до услуге статуса (покушавам поново)","status.updated":"ажурирано {ago}","status.justNow":"управо сад","status.min":"пре {n} мин","status.hours":"пре {n} ч","status.days":"пре {n} д","privacy.title":"AI-gile: шта чувамо","privacy.h1":"Шта чувамо","privacy.lede":"Укратко: само оно што нам пошаљеш, и то не задуго.","privacy.only":"Само оно што нам пошаљеш: оно што упишеш у формулар, на пример свој мејл. Ништа друго о теби.","privacy.sealed":"Запечаћено је тако да га наш сервер не може прочитати: у твом прегледачу пре него што крене (у старијем прегледачу у тренутку кад стигне). Може да га отвори само наша табла.","privacy.server":"Брише се са сервера чим стигне на нашу таблу. Све што је тамо остало и после 30 дана свакако се брише.","privacy.board":"На нашој табли га чувамо само док ти не одговоримо, а онда га и тамо бришемо.","privacy.none":"Без трагача, без колачића, без аналитике.","privacy.local":"Твој језик и избор светле или тамне теме остају у твом прегледачу. Никад нам се не шаљу.","privacy.ask":"Желиш да нестане раније? Одговори на наш мејл и реци нам.","live.h2":"Гледајте како се гради, уживо","live.caption":"Свака картица је скривена: видите облик посла, а не речи.","live.watching.one":"уживо: {n} гледа","live.watching.other":"уживо: {n} гледа","live.last.now":"Последња картица је премештена управо сада","live.last.min.one":"Последња картица је премештена пре {n} минут","live.last.min.other":"Последња картица је премештена пре {n} минута","live.last.hour.one":"Последња картица је премештена пре {n} сат","live.last.hour.other":"Последња картица је премештена пре {n} сати","live.last.day.one":"Последња картица је премештена пре {n} дан","live.last.day.other":"Последња картица је премештена пре {n} дана","live.offline":"Табла уживо мало одмара. Навратите ускоро.","live.cols":"Backlog|Треба урадити|У току|Тим проверава|Чека твој тест|За тим|Готово","pitch.words.few":"{n} речи","pitch.letters.few":"{n} слова","pitch.chars.few":"{n} знака","count.line.html.few":"{n} картице на табли управо сад","tl.cards.few":"{n} картице","live.last.min.few":"Последња картица је премештена пре {n} минута","live.last.hour.few":"Последња картица је премештена пре {n} сата","live.last.day.few":"Последња картица је премештена пре {n} дана"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Канбан.","Роботи.","Делегирано."]},{"n":2,"texts":["Канбан, аутоматизован.","Агенти, организовани.","Идеје, изграђене."]},{"n":3,"texts":["Канбан за роботе.","Идеје постају функције.","Бесплатан канбан агената."]},{"n":5,"texts":["Канбан табла коју воде агенти.","Ти пишеш картице. Агенти граде.","Бесплатно, локално, тестирано, помало смешно."]},{"n":8,"texts":["Бесплатна канбан табла на којој раде AI агенти.","Напиши идеју. Агенти је граде. Ти прихваташ.","Agile за једног човека и много стрпљивих робота."]},{"n":13,"texts":["Канбан табла на твом рачунару на којој AI агенти узимају картице и граде.","Напиши идеју. Тим агената је гради. Тестер је проверава, а ти одлучујеш.","Бесплатно, без налога и трагача: једна табла, пар робота и ти као шеф."]},{"n":21,"texts":["AI-gile је канбан табла за рад са AI агентима који пишу код. Они узимају картице; ти их тестираш и прихваташ.","Сваки пројекат добија вођу и тим AI агената. Коментариши било коју картицу и тим се хвата посла.","Бесплатна, лична табла задатака која ради на твом рачунару. Радници су роботи. Онај који каже да је ти."]},{"n":34,"texts":["Идеје стављаш на таблу. Тим AI агената од њих прави функције које раде, тестира их и враћа ти их са корацима за пробу. Ништа се не рачуна као готово док ти то не кажеш.","AI-gile је кућна канбан табла коју је Рич направио уз пуно помоћи агената којима сада управља. Бесплатна је, ради на твом рачунару и дели се са пријатељима, не продаје се.","Замисли обичну канбан таблу, са колонама од Backlog-а до Готово, само што картице узимају AI агенти. Јављају напредак, питају кад западну и увек сачекају твој палац горе."]},{"n":55,"texts":["AI-gile је канбан табла на којој тим чине AI агенти. Сваки пројекат има вођу који планира посао и помоћнике који граде. Кад је функција спремна, AI тестер је проба и направи снимак екрана, а онда стиже у твоју гомилу. Прихвати је, или коментариши па је раде поново.","Почело је као начин једне особе да прати много AI сесија кодирања одједном, а израсло је у праву таблу. Ради на твом рачунару, не тражи налог и нема трагача. Бесплатна је за пријатеље и радознале. Такође је недовршена, па очекуј грубе ивице и по неко изненађење.","Ево поштене верзије. И даље мораш сам да имаш идеје, и даље мораш сам да провериш резултате. Све између ради AI-gile: држи картице у реду, буди правог агента кад оставиш коментар, показује тачно шта се променило и све то сабира у једну кратку гомилу за тебе, па нема лутања од апликације до апликације."]},{"n":89,"texts":["AI-gile је бесплатна канбан табла коју покрећеш на свом рачунару. Уместо људи, сваки пројекат има тим AI агената: вођу који твоје идеје претвара у картице и план, и помоћнике који узимају картице по приоритету. Кад је нешто направљено, AI тестер прати кораке за тест и показује ти шта је видео. Затим чека у једној гомили која се зове За тебе. Прихватиш га, или коментаришеш и тим покушава поново. Ништа никад не стигне до Готово без тебе.","Неке ствари које можда не очекујеш. Ноћна стража допуњује колону Треба урадити док ти спаваш, бирајући картице којима не треба твој одговор. Бројач токена показује колико су агенти потрошили данас и ове недеље, а No Token Mode им каже да престану да троше. Можеш да пишеш пријатељима, а приватне поруке су шифроване од краја до краја. Табла говори око 120 језика, међу њима холандски, фламански, гусарски и клингонски. Ништа од тога не кошта ни динар, а ни ко ти га не покушава продати.","AI-gile је мали, лични пројекат, а не компанија. Рич је хтео да води неколико AI пројеката кодирања без отварања сваке апликације да провери стање, па су он и агенти направили таблу за то, а онда су помоћу ње направили остатак ње саме. У затвореној је пре-алфи, што значи да ради, углавном, за шачицу пријатеља. Нема странице са ценама, билтена ни плана раста. Ако ти звучи корисно, можеш да затражиш да пробаш кад се мало више отвори."]},{"n":144,"texts":["AI-gile је канбан табла за једног човека и много AI агената. Ради на твом рачунару и потпуно је бесплатна. Додајеш пројекте, и сваки пројекат добија вођу и мали тим. Ћаскаш са вођом, помало као на Discordu, и описујеш идеју; вођа је претвара у картице и план, па чека да притиснеш Крени. Тим пролази кроз картице по приоритету, помоћу једноставног алата за командну линију направљеног за језичке моделе. Пре него што ти се нешто врати, AI тестер прати кораке у копији апликације и прилаже снимак екрана. Готов посао стиже у твоју гомилу са измењеним фајловима и разликом. Прихватиш га, или оставиш коментар па се тим пробуди и покуша поново. Само ти можеш да преместиш картицу у Готово.","Отприлике један дан са AI-gile. Увече оставиш пар коментара: ово дугме је на погрешном месту, она листа треба да буде сортирана, може ли тамни режим. Одеш на спавање. Агенти прочитају коментаре, направе измене, тестирају их и врате ти их. Ако се Треба урадити испразни, ноћна стража га допуни из бекклога картицама којима не треба твој одговор. Ујутру те чека једна кратка гомила: пар питања и неколико ствари за пробу, свака са корацима које може да прати и поспана особа и са снимком екрана како ради. Кликнеш, прихватиш добре и вратиш остале. Бројач токена показује колико је све то потрошило, а No Token Mode је ту за скромније недеље. Затим доручкујеш, а у томе агенти још не могу да помогну.","Прво, шта AI-gile није. Није стартап, није на продају и нико не скупља твоје податке. То је бесплатна табла која ради на твом рачунару, без налога, без трагача и без колачића. А шта јесте: једно уредно место да видиш све своје AI пројекте кодирања одједном, са тимом агената који раде картице и тобом који доносиш одлуке. Спаја сродне картице, поправља збркане наслове и пази колико код остаје сажет. Говори око 120 језика, од холандског и фламанског до гусарског и клингонског. Пријатељи могу да пишу једни другима, приватно и шифровано. Направили су га Рич и велики број стрпљивих агената, углавном користећи њега самог. У затвореној је пре-алфи, па је на местима груб. Ако звучи забавно, лепо питај и можда уђеш раније."]}],"quips":{"1":"Једна реч. Смело. Можда превише смело.","3":"Три речи. Већ поштеније од већине страница производа.","8":"Осам речи. И даље краће од стендапа.","21":"Дужине су, успут, story points. Наравно да јесу.","55":"Педесет пет речи. Две картице су завршене док си ово читао.","144":"То је она дуга. Не постоји 233. Агенти су отишли на спавање."}},"timeline":{"first-idea.name":"Прва идеја","first-idea.line":"Сасвим први разговор, пре него што је постојао иједан ред кода.","first-board.name":"Прва табла","first-board.line":"Табла која прати сопствену изградњу: картице, колоне, превлачење, пројекти.","team-roles.name":"Тим и улоге","team-roles.line":"Профили агената, шаблони тимова, простори и ко шта ради.","install.name":"Инсталација и издања","install.line":"Зип који пријатељ може да инсталира, самоажурирање, канали и повратак на старо.","usage-saver.name":"Штедња потрошње","usage-saver.line":"Мери колико коштају покретања, држи код сажетим, чува твоје ограничење.","friends.name":"Пријатељи и дељење","friends.line":"Приватне поруке, прикривени релеј, позивнице, улоге и дељени пројекти.","languages.name":"Језици","languages.line":"Сваки текст на екрану у језичком фајлу, прво холандски и фламански.","ai-tester.name":"AI тестер","ai-tester.line":"Тестер прво проверава сваку предају и показује шта је видео.","website.name":"Веб-сајт","website.line":"aigile.lol, тизер и ова временска линија.","streaming.name":"Ћаскање и стриминг","streaming.line":"Discord, Twitch, OBS, стример режим, GIF-ови и емоџији.","no-ai.name":"Издање без AI","no-ai.line":"Табла за људе који кодирају без AI, и јавне табле.","night-watch.name":"Ноћна стража","night-watch.line":"Чувар и Scrum Master држе тимове на задатку док ти спаваш.","p-more.name":"Све остало","p-more.line":"Мање идеје које чекају на ред.","p-android.name":"Телефон и Android","p-android.line":"Допри до табле са телефона, а затим изворна Android апликација.","p-release.name":"Алфа и даље","p-release.line":"Затворена алфа, живи сајт, па бета.","p-languages.name":"Још језика","p-languages.line":"Више од сто језика и режим уроњења за оне који уче.","p-engines.name":"Још AI мотора","p-engines.line":"Изабери Claude, Codex или Gemini за сваког агента.","p-pro.name":"Професионална пракса","p-pro.line":"Ознаке ризика, капије за спајање, картице за инциденте и заштитне ограде.","p-self.name":"Брига о теби","p-self.line":"Режим уморног, подсетници за бригу о себи и 4:20.","p-servers.name":"Сервери и раст","p-servers.line":"Глобална подешавања сервера, улоге и планирање раста.","p-livestream.name":"Додаци за стриминг","p-livestream.line":"Twitch ћаскање, прилагођени емоџији и јавни приказ уживо."},"words":{"button":"📖 Стручни изрази","h":"📖 Објашњене речи","intro":"Речи на које наилазиш у AI-gile, објашњене једноставно: како нешто направити, безбедно мењати, одржавати да ради за људе који га користе и радити као тим са AI.","search":"Претражи реч…","none":"Ниједна реч се не поклапа.","close":"Затвори","count":{"one":"{count} реч","other":"{count} речи"},"groups":[{"id":"build","name":"🛠️ Прављење"},{"id":"change","name":"🔀 Безбедне измене"},{"id":"run","name":"🛎️ Рад сервиса"},{"id":"team","name":"🤝 Рад у тиму (и са AI)"}],"list":[{"id":"repo","g":"build","word":"Репозиторијум","text":"Фолдер пројекта са кодом и његовом целом историјом комитова, обично чуваном и на GitHub-у.","also":["репозиторијум","репо","репоа","repo","repository"]},{"id":"branch","g":"build","word":"Грана","text":"Посебна линија рада у коду, да се измене могу радити а да се не дира главна верзија.","also":["грана","гране","грани","грану","бранч","branch","branches"]},{"id":"commit","g":"build","word":"Комит","text":"Сачуван снимак кода са кратком белешком шта је промењено. Увек можеш да се вратиш на неки.","also":["комит","комита","комити","комитова","commit","commits"]},{"id":"push","g":"build","word":"Push","text":"Слање сачуваних снимака (комитова) са овог рачунара на GitHub, да буду резервна копија и да се деле."},{"id":"merge","g":"build","word":"Спајање","text":"Враћање измена једне гране у главну верзију."},{"id":"pr","g":"build","word":"Pull request","text":"Захтев да се измене једне гране провере и споје у главну верзију.","also":["PR","pull request"]},{"id":"refactor","g":"build","word":"Рефакторисање","text":"Сређивање кода без промене онога што ради: мањи фајлови, јаснији називи, мање понављања."},{"id":"bug","g":"build","word":"Баг","text":"Нешто што не ради како треба.","also":["баг","бага","багу","багови","багова","bug","bugs"]},{"id":"test","g":"build","word":"Тест","text":"Испробавање готовог посла да се провери да ли ради оно што је тражено, пре него што га прихватиш.","also":["тест","теста","тестови","тестова","тестирање","test","tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Скраћеница за quality assurance, обезбеђење квалитета: аутоматске провере које се покрећу пре него што било шта иде уживо. Кад је QA црвен, нешто није прошло и не може уживо док се то не поправи.","also":["провера квалитета","провере квалитета","обезбеђење квалитета"]},{"id":"deploy","g":"change","word":"Деплој","text":"Пуштање нове верзије уживо, на пример на сервер где је људи користе."},{"id":"release","g":"change","word":"Издање","text":"Именован пакет завршеног посла који иде уживо заједно, са кратким белешкама о томе шта се променило. 🚀 Издања пишу белешке из завршених картица.","also":["издања","release","релиз"]},{"id":"rollback","g":"change","word":"Враћање уназад","text":"Повратак на последњу верзију која је радила, кад нова прави проблеме. У AI-gile од тога настаје листа корака за поништавање који су записани уз сваку измену.","also":["rollback","врати уназад","враћено уназад"]},{"id":"live","g":"change","word":"Уживо","text":"Права верзија коју људи користе, за разлику од копије за испробавање. Програмери је зову и продукција.","also":["продукција","live"],"noTip":1},{"id":"change","g":"change","word":"Измена","text":"Планирана измена нечега на шта се људи ослањају, прво записана: шта, зашто, ризик, када и како је поништити. Почни је са 🔀 Поднеси измену.","also":["измене","захтев за измену","захтеви за измену"],"noTip":1},{"id":"risk","g":"change","word":"Ризик","text":"Нешто што би могло да пође наопако, оцењено по томе колико је вероватно и колико би било лоше. ⚠️ Ризици их држе на једној листи, највећа оцена прва, сваки са датумом кад га поново погледати.","also":["ризици","регистар ризика"]},{"id":"chgwin","g":"change","word":"Прозор за измене","text":"Термини кад измене смеју да иду уживо, на пример миран уторак увече. Ван прозора картица измене не може да се заврши, осим ако је хитно.","also":["прозори за измене","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Брзо гласање тик пре него што измена иде уживо: свако ко треба да одобри каже Go или No go. Иде се даље само кад се сложе.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Одобрење","text":"Чекање на да пре него што посао почне. Картица коју поднесе пријатељ, или измена, чека у ✅ Одобрењима док је не одобриш или одбијеш.","also":["одобрења","одобри"]},{"id":"quiettime","g":"change","word":"Тихо време","text":"Период, као стрим, демо или ноћ, кад ништа не иде уживо. Тимови и даље раде и тестирају, али објављивање чека да се заврши. На другим местима се зове замрзавање измена.","also":["тихи термини","замрзавање измена","change freeze"]},{"id":"service","g":"run","word":"Сервис","text":"Нешто што си направио и на шта се људи ослањају, као сајт или апликација, о чему се води рачуна да стално ради. Означи „Овај пројекат је сервис“ и напиши шта нуди, ко га користи и ко дежура.","also":["сервиси","услуга","услуге"]},{"id":"uptime","g":"run","word":"Провера доступности","text":"Аутоматска провера на сваких неколико минута да ли твој сервис још одговара. Ако не успе неколико пута заредом, AI-gile сам отвара картицу инцидента.","also":["доступност","uptime","провере доступности"]},{"id":"statuspage","g":"run","word":"Страница статуса","text":"Јавна страница која показује да ли сервис ради (зелено, наранџасто или црвено), са последњом вешћу, да би људи који га користе могли сами да провере уместо да питају.","also":["странице статуса","статусна страница","status page"]},{"id":"incident","g":"run","word":"Инцидент","text":"Нешто што је управо сада покварено за људе који то користе, на пример кад сајт не ради. Картица 🔥 инцидента прескаче ред: прво да поново проради.","also":["инциденти","испад"]},{"id":"major","g":"run","word":"Велики инцидент","text":"Велики инцидент: погођено је много људи, или су новац или подаци у опасности. Једно дугме ставља све тимове на њега (рој), буди онога ко дежура и тражи вест о статусу на сваких 30 минута.","also":["велики инциденти","major incident"]},{"id":"oncall","g":"run","word":"Дежурство","text":"Бити онај ко се јавља кад се нешто поквари, чак и ноћу. Сваки сервис има дежурног члана тима кога први буде због његових инцидената.","also":["дежурни","дежура","on call","on-call"]},{"id":"replyby","g":"run","word":"Рок за одговор","text":"Колико картица сме да чека на први одговор, на пример сат времена за инцидент. После тога добија црвени сат, да се ништа не заборави у тишини. Зове се и циљно време одзива.","also":["рокови за одговор","циљно време одзива"]},{"id":"postmortem","g":"run","word":"Анализа после инцидента","text":"Кратак поглед уназад после инцидента: шта се десило, шта је помогло и шта променити, без окривљавања било кога. Инцидент не може да се затвори без ње. Често се зове и post-mortem.","also":["анализе после инцидента","post-mortem","постмортем"]},{"id":"problem","g":"run","word":"Проблем","text":"Скривени узрок иза једног или више инцидената. Картица 🧩 проблема спаја инциденте који се стално враћају, да се узрок нађе и поправи заувек.","also":["проблеми"],"noTip":1},{"id":"rootcause","g":"run","word":"Основни узрок","text":"Прави разлог зашто се нешто покварило, а не само оно што си видео да не ради. Поправи основни узрок и инцидент престаје да се враћа.","also":["основни узроци","root cause","корени узрок"]},{"id":"workaround","g":"run","word":"Заобилазно решење","text":"Начин да ствари раде док права поправка не буде спремна, на пример рестарт кад се нешто заглави. Записује се на картицу проблема да нико не мора поново да га смишља.","also":["заобилазна решења","workaround","привремено решење"]},{"id":"knownerror","g":"run","word":"Позната грешка","text":"Проблем чији је узрок јасан и који има заобилазно решење, али још није поправљен. 🧩 Познате грешке их набрајају, да сви користе заобилазно решење уместо да поново копају.","also":["познате грешке","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Упутство корак по корак за поправку познате врсте квара, да се сваки пут уради исто и брзо. После великог инцидента тим ти га може предложити да га одобриш.","also":["runbook-ови","ранбук","упутство за рад"]},{"id":"backup","g":"run","word":"Резервна копија","text":"Сачувана копија твојих података од раније, на коју можеш да се ослониш ако се нешто изгуби или оштети. AI-gile сваки дан прави резервну копију твојих табли.","also":["резервне копије","бекап","backup"]},{"id":"restore","g":"run","word":"Враћање података","text":"Враћање података из резервне копије. Резервна копија заиста вреди тек кад знаш да може да се врати, па вреди то повремено испробати.","also":["врати","враћено","restore","опоравак"]},{"id":"backlog","g":"team","word":"Backlog","text":"Идеје и посао који још нису планирани. Ништа од тога се не ради док се не премести у „Треба урадити“."},{"id":"sprint","g":"team","word":"Спринт","text":"Кратак период рада (често недеља или две) са договореним скупом картица које треба завршити.","also":["спринт","спринта","спринту","спринтом","спринтови","спринтова","sprint","sprints"]},{"id":"standup","g":"team","word":"Стендап","text":"Брза провера: шта је сваки члан тима урадио, шта ради следеће и шта га спречава.","also":["стендап","стендапа","стендапу","стендапови","стендапова","standup","stand-up","stand-ups"]},{"id":"kanban","g":"team","word":"Канбан","text":"Табла са колонама (Треба урадити, У току, Готово) на којој картице иду слева надесно како посао напредује."},{"id":"wip","g":"team","word":"WIP лимит","text":"Work in progress (посао у току): највише картица које колона треба да држи, да тим заврши ствари пре него што започне нове.","also":["WIP","wip лимит","лимит"]},{"id":"dod","g":"team","word":"Дефиниција Завршено","text":"Кратка листа тима шта значи „завршено“, на пример тестирано и објашњено, пре него што ти картица стигне. Њен близанац, Дефиниција Спремно за почетак, каже кад је картица довољно јасна да се почне.","also":["Definition of Done","Дефиниција Спремно за почетак","Definition of Ready"]},{"id":"testpile","g":"team","word":"Гомила за тестове","text":"Завршене картице које чекају да их испробаш, једна за другом. Прихвати једну или је врати са белешком, и стиже следећа.","also":["гомиле за тестове"]},{"id":"retro","g":"team","word":"Ретро","text":"Поглед уназад на то како тим ради, да се договори једна ствар која ће се радити боље. У AI-gile ретро предлаже измену начина рада тима, а ти кажеш Може или Још не.","also":["retro","ретроспектива","ретроспективе"]},{"id":"peerreview","g":"team","word":"Преглед колега","text":"Други пар очију: други AI проверава посао сваке картице пре него што стигне до тебе, да прође мање грешака.","also":["peer review","преглед кода","code review"]},{"id":"swarm","g":"team","word":"Рој","text":"Сви на палубу: сваки тим оставља други посао и помаже на једном хитном пројекту док се не реши. Остали пројекти у међувремену чекају.","also":["swarm","swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"Онај ко одржава да посао тече: примећује заглављене картице, гура тимове и подсећа те шта чека. У AI-gile то ради Lead Scrum Master у свим пројектима.","also":["Lead Scrum Master","Скрам мастер"]},{"id":"agent","g":"team","word":"Агент","text":"AI који самостално ради на задатку: чита код, прави измене, покреће провере и јавља се.","also":["агент","агента","агенти","агената","agent","agents"]},{"id":"token","g":"team","word":"Токен","text":"Јединица у којој се броји потрошња AI-ја: отприлике неколико слова прочитаног или написаног текста. Мање токена, више остало од плана.","also":["токен","токена","токени","токена","token","tokens"]},{"id":"hook","g":"team","word":"Hook","text":"Мала команда која се сама покреће у одређеном тренутку, нпр. када почне AI сесија, да тим чује твоје коментаре.","also":["hook","hook-ови","hook-а","hooks"]}]}};
